-- ===== Branch Pulse: load of company CMP000 (generated by infra/export-dev-data.sh; this block runs before the data) =====
-- Run the whole file in ONE transaction, as the postgres user, after the migrations:
--   psql -U postgres -d branch_pulse -v ON_ERROR_STOP=1 --single-transaction -f data.sql
-- Re-running it replaces the company again. Other companies and the Super Admin are never touched.
SET session_replication_role = replica; -- ordering of rows does not matter while loading

-- the data was exported from a database at migration 20261028000100_password_policy: production must be at least that far
DO $chk$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM public._prisma_migrations WHERE migration_name = '20261028000100_password_policy' AND finished_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Production database is behind (missing migration 20261028000100_password_policy). git pull, rebuild (docker compose ... build) and run: docker compose ... run --rm migrate  - then load this file again';
  END IF;
END $chk$;

-- ---- helper functions (session only)
-- Shared by export-dev-data.sh and import-dev-data.sh. The database has almost no foreign keys (Prisma runs without
-- database-level relations), so "everything that belongs to a company" is found here by following the id columns.
--
--   1. delete the root rows of the companies to remove (companies, and every table with a company_id column)
--   2. SELECT pg_temp.bp_sweep();  -- delete every row whose branch / user / role / purchase ... no longer exists
--
-- Run it with session_replication_role = replica. The functions live only in the current session.
CREATE OR REPLACE FUNCTION pg_temp.bp_delete_company(cond text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE t text;
BEGIN
  FOR t IN
    SELECT c.table_name FROM information_schema.columns c
    JOIN information_schema.tables x ON x.table_schema = c.table_schema AND x.table_name = c.table_name AND x.table_type = 'BASE TABLE'
    WHERE c.table_schema = 'public' AND c.column_name = 'company_id'
  LOOP
    EXECUTE format('DELETE FROM public.%I WHERE company_id IN (SELECT id FROM public.companies WHERE %s)', t, cond);
  END LOOP;
  EXECUTE format('DELETE FROM public.companies WHERE %s', cond);
END $$;

CREATE OR REPLACE FUNCTION pg_temp.bp_sweep() RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  r record;
  pass int;
BEGIN
  FOR pass IN 1..3 LOOP -- parents can themselves be children (purchases -> purchase_items), so repeat
    -- every table with a location_id column
    FOR r IN
      SELECT c.table_name FROM information_schema.columns c
      JOIN information_schema.tables x ON x.table_schema = c.table_schema AND x.table_name = c.table_name AND x.table_type = 'BASE TABLE'
      WHERE c.table_schema = 'public' AND c.column_name = 'location_id'
    LOOP
      EXECUTE format('DELETE FROM public.%I WHERE location_id IS NOT NULL AND location_id NOT IN (SELECT id FROM public.locations)', r.table_name);
    END LOOP;
    -- child table, id column, parent table
    FOR r IN
      SELECT * FROM (VALUES
        ('stock_transfers', 'from_location_id', 'locations'), ('stock_transfers', 'to_location_id', 'locations'),
        ('user_roles', 'user_id', 'users'), ('user_roles', 'role_id', 'roles'), ('user_locations', 'user_id', 'users'),
        ('role_permissions', 'role_id', 'roles'), ('sessions', 'user_id', 'users'), ('sync_operations', 'user_id', 'users'),
        ('notification_deliveries', 'notification_id', 'notifications'), ('notification_deliveries', 'user_id', 'users'),
        ('purchase_items', 'purchase_id', 'purchases'), ('recipe_items', 'recipe_id', 'recipes'),
        ('recipe_cost_snapshots', 'recipe_id', 'recipes'), ('supplier_items', 'supplier_id', 'suppliers'),
        ('stock_count_items', 'stock_count_id', 'stock_counts'), ('stock_transfer_items', 'transfer_id', 'stock_transfers'),
        ('advance_repayments', 'advance_id', 'employee_advances'), ('daily_closing_events', 'daily_closing_id', 'daily_closing'),
        ('attendance', 'employee_id', 'employees'), ('salary', 'employee_id', 'employees'), ('employee_advances', 'employee_id', 'employees')
      ) AS m(child, col, parent)
    LOOP
      EXECUTE format('DELETE FROM public.%I WHERE %I IS NOT NULL AND %I NOT IN (SELECT id FROM public.%I)', r.child, r.col, r.col, r.parent);
    END LOOP;
  END LOOP;
END $$;

-- ---- permissions and units are shared master data with different ids in each database: dev id -> code
CREATE TEMP TABLE bp_idmap (kind text, code text, dev_id uuid);
DO $chk$ DECLARE missing text; BEGIN
  SELECT string_agg(m.kind || ':' || m.code, ', ') INTO missing FROM pg_temp.bp_idmap m
  WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE m.kind = 'permissions' AND p.code = m.code)
    AND NOT EXISTS (SELECT 1 FROM public.units u WHERE m.kind = 'units' AND u.code = m.code);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Production is missing permissions/units that dev has (the migrations differ): %', missing;
  END IF;
END $chk$;

-- ---- remove the previous copy of the company: by code, by id (a copy loaded earlier under an old code) and, if given,
--      other test companies:  psql -v also_remove="'CMP002','CMP003'" ...
SELECT pg_temp.bp_delete_company($c$code = 'CMP000' OR id = 'f2328b4f-e294-41ec-80a4-3d3c7645e3f5'$c$);
\if :{?also_remove}
SELECT pg_temp.bp_delete_company(format('code IN (%s)', :'also_remove'));
\endif
SELECT pg_temp.bp_sweep();

-- ---- a user whose username / mobile is already taken gets the next free number instead of failing the load
CREATE FUNCTION public.bp_fix_user_keys() RETURNS trigger LANGUAGE plpgsql AS $f$
DECLARE
  n bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE username IN (NEW.username, NEW.mobile) OR mobile IN (NEW.username, NEW.mobile)) THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.mobile, NEW.username) !~ '^\d{10}$' THEN
    RETURN NEW; -- not a mobile-style key: let the unique index report it
  END IF;
  n := COALESCE(NEW.mobile, NEW.username)::bigint;
  LOOP
    n := n + 1;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.users WHERE username = n::text OR mobile = n::text);
  END LOOP;
  RAISE NOTICE 'user key % already in use: % now signs in as %', COALESCE(NEW.mobile, NEW.username), NEW.full_name, n;
  IF NEW.username = COALESCE(NEW.mobile, NEW.username) THEN NEW.username := n::text; END IF;
  IF NEW.mobile IS NOT NULL THEN NEW.mobile := n::text; END IF;
  RETURN NEW;
END $f$;
CREATE TRIGGER bp_fix_user_keys BEFORE INSERT ON public.users FOR EACH ROW EXECUTE FUNCTION public.bp_fix_user_keys();
ALTER TABLE public.users ENABLE ALWAYS TRIGGER bp_fix_user_keys;
